#!/usr/bin/env python3
"""restart_count.py -- v20n: the fresh-start price, regenerated by script.

Fixes verdict e9ee1dbc point 4, second half: v20m re-derived the chain price in
the NOTE (7 products per doubling, 11 per window addition) but the JSON consumer
still carried 319 ref per scalar multiplication (one ref per doubling).  Here
the JSON is the ONLY source: every number is computed here, written to
evidence/restart-count.json, and ledger.py LOADS that file for FRESH_REF /
RESTART_REF (the self-audit asserts ledger rows == JSON rows on the staged tree,
so a hand-copied constant cannot reappear).

Prices, exact integers of 383-instruction field products (the measured
blst_fp_mul row; squarings charged at the multiply price):
  point doubling        2M + 5S = 7 products
  window addition       11M
  scalar action         255 doublings + 64 window additions (4-bit window)
The doubling/addition op counts are the itemised chain structure the shipped
kernels implement (bls_fp_ops.c inlines to one unit, so the disassembly cannot
separate mul from sqr -- stated, not papered over).
"""
import json
import os
import sys

HERE = os.path.dirname(os.path.abspath(__file__))
D = os.path.dirname(HERE)
sys.path.insert(0, HERE)
sys.path.insert(0, D)

C = 1000                 # secp256k1-ecdlp protected normalization (NOT the bls C=2000)
M_INSN = 92              # measured 4-limb Montgomery CIOS mul on this host (disasm)
S_INSN = 89              # measured 4x4 schoolbook product (disasm); squaring <= multiply
INV_INSN = (254 + 11) * M_INSN
SCALAR_BITS = 256
WINDOW = 4
DOUBLES = SCALAR_BITS - 1        # 255
ADDS = SCALAR_BITS // WINDOW     # 64
DBL_PROD = 2 + 5
ADD_PROD = 11

DBL_INSN = DBL_PROD * M_INSN
ADD_INSN = ADD_PROD * M_INSN
CHAIN_INSN = DOUBLES * DBL_INSN + ADDS * ADD_INSN
DBL_REF = DBL_INSN / C
ADD_REF = ADD_INSN / C
CHAIN_REF = CHAIN_INSN / C
ROWS = [
    ("point doubling 2M+5S at 4-limb insn/product", DBL_INSN, "insn"),
    ("window addition 11M at 4-limb insn/product", ADD_INSN, "insn"),
    ("255 doublings + 64 window additions (one 256-bit scalar action)",
     CHAIN_INSN, "insn"),
    ("two scalar actions [a]P0 and [c]T", 2 * CHAIN_INSN, "insn"),
    ("S = [a]P0 + [c]T, one batched mixed affine addition", C, "insn"),
    ("normalization S -> affine: one batched-inverse share", INV_INSN, "insn"),
    ("class key: two fixed-constant 4-limb products + min/max + sign", 40, "insn"),
    ("lane reset: esc_run=0, prev=class, restart flag, counters, segment", 30, "insn"),
]
FRESH_INSN = sum(v for _o, v, _u in ROWS)
FRESH_REF = FRESH_INSN / C


def main():
    out = os.path.join(D, "evidence", "restart-count.json")
    res = {
        "test": "restart_count_v20n",
        "unit": {"C": C, "M_INSN": M_INSN, "S_INSN": S_INSN, "INV_INSN": INV_INSN},
        "chain": {"doubles": DOUBLES, "window_adds": ADDS, "window_bits": WINDOW,
                  "dbl_prod": DBL_PROD, "add_prod": ADD_PROD,
                  "dbl_insn": DBL_INSN, "add_insn": ADD_INSN,
                  "chain_insn": CHAIN_INSN, "chain_ref": CHAIN_REF,
                  "ratio_to_v20l_319": CHAIN_REF / 319.0},
        "rows": [{"op": o, "value": v, "unit": u} for o, v, u in ROWS],
        "fresh_insn_equivalent": FRESH_INSN,
        "fresh_ref": FRESH_REF,
        "v20j_priced_insn": 42,
        "ratio": FRESH_REF / (42 / C),
        "v20l_priced_ref_per_scalar_mult": 319.0,
        "repricing_factor": CHAIN_REF / 319.0,
    }
    try:
        import ledger
        res["meter_cap_ref"] = float(ledger.METER_CAP)
        res["starts_admitted_by_meter"] = float(ledger.METER_CAP) / FRESH_REF
        res["ledger_restart_ref"] = float(ledger.RESTART_REF)
        res["ledger_consumes_json"] = (
            abs(float(ledger.FRESH_REF) - FRESH_REF) < 1e-9)
    except Exception as exc:                      # pragma: no cover
        res["ledger_consumes_json"] = False
        res["ledger_error"] = repr(exc)
    with open(out, "w") as f:
        json.dump(res, f, sort_keys=True, indent=1)
    print("fresh start %.4f ref = %.0f insn (chain %.3f ref/scalar action; "
          "v20l 319.000 -> x%.3f)" % (FRESH_REF, FRESH_INSN, CHAIN_REF,
                                      CHAIN_REF / 319.0))
    for o, v, u in ROWS:
        print("  %-66s %9d %s" % (o, v, u))


if __name__ == "__main__":
    main()
